// ATMOS — notebook charts, drawn as plain SVG from window.ATMOS_DATA (data.js).
// data.js is generated by backend/build_site_data.py, which re-runs the notebook
// pipeline and checks every confusion matrix against the notebook outputs.
(function () {
  const D = window.ATMOS_DATA;
  if (!D) return;
  const NS = "http://www.w3.org/2000/svg";
  const COLORS = {
    "Decision Tree": "#e9a426", "Random Forest": "#0e7c7b", "SVC": "#2f6f9f",
    "KNN": "#8b5cf6", "Logistic Regression": "#b45309",
  };
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const fmt = (n) => Number(n).toLocaleString("en-US");
  const put = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };

  // ---- Target distribution (notebook cell 9) ----
  (function target() {
    const { dry, rain } = D.target, total = dry + rain;
    const row = (label, n, cls) => `
      <div class="hbar-row"><span class="hbar-name">${label}</span>
        <span class="hbar-track"><span class="hbar-fill ${cls}" style="width:${(n / total) * 100}%"></span></span>
        <span class="hbar-val">${fmt(n)} · ${((n / total) * 100).toFixed(1)}%</span></div>`;
    put("chartTarget", row("No rain (0)", dry, "fill-sun") + row("Rain (1)", rain, "fill-rain") +
      `<p class="chart-note">A model that always says “no rain” already scores ${((dry / total) * 100).toFixed(1)}% — the baseline to beat.</p>`);
  })();

  // ---- Rain rate by cloud cover (supports the “0% at 0–4, ~42% at 5–8” claim) ----
  (function cloud() {
    const r = D.rain_rate_by_cloud;
    const bars = Object.keys(r).map((k) => {
      const v = r[k];
      return `<div class="vbar"><span class="vbar-val">${(v * 100).toFixed(1)}%</span>
        <span class="vbar-col"><span class="vbar-fill ${v > 0 ? "fill-rain" : "fill-sun"}" style="height:${Math.max(2, v * 200)}%"></span></span>
        <span class="vbar-name">${k}</span></div>`;
    }).join("");
    put("chartCloud", `<div class="vbars">${bars}</div><p class="chart-note">Cloud cover (oktas) → share of days followed by rain. Nothing rains below 5 oktas.</p>`);
  })();

  // ---- Feature importances, all 8 (notebook cell 27) ----
  (function imp() {
    const entries = Object.entries(D.importances);
    const max = entries[0][1];
    put("chartImportance", entries.map(([f, v]) => `
      <div class="hbar-row"><span class="hbar-name">${f}</span>
        <span class="hbar-track"><span class="hbar-fill fill-teal" style="width:${Math.max(0.6, (v / max) * 100)}%"></span></span>
        <span class="hbar-val">${v.toFixed(4)} · ${(v * 100).toFixed(1)}%</span></div>`).join(""));
  })();

  // ---- Correlation heatmap (notebook cell 10) ----
  (function corr() {
    const { labels, matrix } = D.correlation;
    const short = { MinTemp: "MinT", MaxTemp: "MaxT", Rainfall: "Rain", Humidity: "Hum", Pressure: "Pres",
      WindSpeed: "Wind", WindGustSpeed: "Gust", Cloud: "Cloud", RainTomorrow: "Target" };
    const color = (v) => {
      const a = Math.min(1, Math.abs(v));
      return v >= 0 ? `rgba(14,124,123,${0.08 + a * 0.85})` : `rgba(180,83,9,${0.08 + a * 0.85})`;
    };
    let html = `<table class="heatmap"><thead><tr><th></th>${labels.map((l) => `<th title="${l}">${short[l]}</th>`).join("")}</tr></thead><tbody>`;
    matrix.forEach((row, i) => {
      html += `<tr><th title="${labels[i]}">${short[labels[i]]}</th>` + row.map((v, j) =>
        `<td style="background:${color(v)};color:${Math.abs(v) > 0.55 ? "#fff" : "#17302e"}" title="${labels[i]} × ${labels[j]} = ${v}">${v.toFixed(2)}</td>`).join("") + "</tr>";
    });
    html += `</tbody></table><p class="chart-note">Only Cloud (+0.466) and Humidity (+0.463) correlate with the target. Rainfall (+0.029) looks useless here but is the third gate of the rule — correlation misses AND-style patterns.</p>`;
    put("chartCorr", html);
  })();

  // ---- Train vs test accuracy (notebook cells 22–23) ----
  (function trainTest() {
    const lo = 0.9, scale = (v) => Math.max(1, ((v - lo) / (1 - lo)) * 100);
    const models = [...D.models].sort((a, b) => b.test_accuracy - a.test_accuracy);
    put("chartTrainTest", models.map((m) => `
      <div class="pair-row"><span class="hbar-name">${m.model}</span>
        <span class="pair-bars">
          <span class="hbar-track"><span class="hbar-fill fill-storm" style="width:${scale(m.train_accuracy)}%"></span></span>
          <span class="hbar-track"><span class="hbar-fill fill-sun" style="width:${scale(m.test_accuracy)}%"></span></span>
        </span>
        <span class="hbar-val">${(m.train_accuracy * 100).toFixed(2)}% / ${(m.test_accuracy * 100).toFixed(2)}%</span></div>`).join("") +
      `<p class="chart-note"><i class="key fill-storm"></i> Train <i class="key fill-sun"></i> Test · bars scaled 90–100%. The train–test gap is the overfitting check: KNN loses 1.8 points, the trees lose none.</p>`);
  })();

  // ---- ROC curves (notebook cell 26) ----
  (function roc() {
    const W = 360, P = 36, S = W - P * 1.5;
    const x = (v) => P + v * S, y = (v) => P / 2 + (1 - v) * S;
    const svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", `0 0 ${W} ${W}`);
    svg.setAttribute("class", "roc-svg");
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", "ROC curves of all five models");
    let inner = `<rect x="${x(0)}" y="${y(1)}" width="${S}" height="${S}" fill="#fbfdfc" stroke="#d7e3de"/>`;
    for (let t = 0; t <= 1.0001; t += 0.25) {
      inner += `<line x1="${x(t)}" y1="${y(0)}" x2="${x(t)}" y2="${y(1)}" stroke="#edf3f0"/>` +
        `<line x1="${x(0)}" y1="${y(t)}" x2="${x(1)}" y2="${y(t)}" stroke="#edf3f0"/>` +
        `<text x="${x(t)}" y="${y(0) + 14}" font-size="10" text-anchor="middle" fill="#5b6f6c">${t}</text>` +
        `<text x="${x(0) - 6}" y="${y(t) + 3}" font-size="10" text-anchor="end" fill="#5b6f6c">${t}</text>`;
    }
    inner += `<line x1="${x(0)}" y1="${y(0)}" x2="${x(1)}" y2="${y(1)}" stroke="#9aa9a6" stroke-dasharray="4 4"/>`;
    // Draw the perfect models last and dashed so the overlapping DT/RF curves stay visible.
    const order = ["Logistic Regression", "KNN", "SVC", "Random Forest", "Decision Tree"];
    order.forEach((name) => {
      const m = D.models.find((mm) => mm.model === name);
      if (!m) return;
      const pts = m.roc.map(([f, t]) => `${x(f).toFixed(1)},${y(t).toFixed(1)}`).join(" ");
      const dash = name === "Decision Tree" ? ' stroke-dasharray="6 5"' : "";
      inner += `<polyline points="${pts}" fill="none" stroke="${COLORS[name]}" stroke-width="2.4"${dash}/>`;
    });
    inner += `<text x="${x(0.5)}" y="${W - 2}" font-size="11" text-anchor="middle" fill="#17302e">False positive rate</text>` +
      `<text x="10" y="${y(0.5)}" font-size="11" text-anchor="middle" fill="#17302e" transform="rotate(-90 10 ${y(0.5)})">True positive rate</text>`;
    svg.innerHTML = inner;
    const host = document.getElementById("chartRoc");
    if (!host) return;
    host.innerHTML = "";
    host.appendChild(svg);
    const legend = document.createElement("div");
    legend.className = "roc-legend";
    legend.innerHTML = [...D.models].sort((a, b) => b.roc_auc - a.roc_auc).map((m) =>
      `<span><i class="key" style="background:${COLORS[m.model]}"></i>${esc(m.model)} · AUC ${m.roc_auc.toFixed(4)}</span>`).join("") +
      `<span><i class="key" style="background:#9aa9a6"></i>Random guess · 0.5</span>`;
    host.appendChild(legend);
  })();

  // ---- Confusion matrices for every model (notebook cells 17–21) ----
  (function cms() {
    const order = ["Decision Tree", "Random Forest", "SVC", "KNN", "Logistic Regression"];
    put("chartCms", order.map((name) => {
      const m = D.models.find((mm) => mm.model === name);
      const [[tn, fp], [fn, tp]] = m.confusion_matrix;
      const cell = (n, good, label) => `<div class="mcm-cell ${good ? "good" : n === 0 ? "zero" : "bad"}"><strong>${fmt(n)}</strong><span>${label}</span></div>`;
      return `<article class="mcm"><h4>${name}</h4>
        <div class="mcm-grid">${cell(tn, true, "true dry")}${cell(fp, false, "false alarm")}${cell(fn, false, "missed rain")}${cell(tp, true, "true rain")}</div>
        <p>${fmt(fp + fn)} mistakes / 11,200</p></article>`;
    }).join(""));
  })();

  // ---- Dataset summary stats (notebook cell 7) ----
  (function summary() {
    const units = { MinTemp: "°C", MaxTemp: "°C", Rainfall: "mm", Humidity: "%", Pressure: "hPa", WindSpeed: "km/h", WindGustSpeed: "km/h", Cloud: "oktas" };
    put("summaryBody", D.features.map((f) => {
      const s = D.summary[f];
      return `<tr><td>${f}</td><td>${units[f]}</td><td>${s.min}</td><td>${s.mean}</td><td>${s.std}</td><td>${s.max}</td><td>${D.importances[f].toFixed(4)}</td></tr>`;
    }).join(""));
  })();
})();
